// This file is generated by AI.

// 项目编辑页: 顶栏 + 左侧(预览 + 场景/资源) + 右侧(选项卡/编辑器/状态栏)。

import { Button } from '@fluentui/react-components';
import { save } from '@tauri-apps/plugin-dialog';
import {
  ArchiveRegular,
  ArrowLeftRegular,
  DocumentTextRegular,
  PanelLeftContractRegular,
  PanelLeftExpandRegular,
  SettingsRegular,
  WeatherMoonRegular,
  WeatherSunnyRegular,
} from '@fluentui/react-icons';
import { useRef, useState, useEffect } from 'react';

import { refreshGitStatus, startGitWatcher, stopGitWatcher } from '../git/status';
import { closeProject } from '../project';
import { PreprocessTab } from '../novel/PreprocessTab';
import { useAppStore } from '../state/store';
import { confirmClose } from '../unsaved';
import { CodeEditor } from './CodeEditor';
import { EditorTabs } from './EditorTabs';
import { GitDiffEditor } from './GitDiffEditor';
import { PreviewPanel } from './PreviewPanel';
import { ProjectTab } from './ProjectTab';
import { RepositoryTab } from './RepositoryTab';
import { ResourceBrowser } from './ResourceBrowser';
import { SceneBrowser } from './SceneBrowser';
import { SnapshotDialog } from './SnapshotDialog';
import { StatusBar } from './StatusBar';

export function EditorPage() {
  const projectPath = useAppStore((s) => s.projectPath);
  const projectName = useAppStore((s) => s.projectName);
  const documents = useAppStore((s) => s.documents);
  const activePath = useAppStore((s) => s.activePath);
  const activeNovelId = useAppStore((s) => s.activeNovelId);
  const openNovelTab = useAppStore((s) => s.openNovelTab);
  const activeDiffId = useAppStore((s) => s.activeDiffId);
  const diffTabs = useAppStore((s) => s.diffTabs);
  const theme = useAppStore((s) => s.theme);
  const updateSettings = useAppStore((s) => s.updateSettings);
  const setSettingsOpen = useAppStore((s) => s.setSettingsOpen);
  const setSettingsCategory = useAppStore((s) => s.setSettingsCategory);

  const [sidebarVisible, setSidebarVisible] = useState(true);
  const [sidebarTab, setSidebarTab] = useState<'scenes' | 'resources' | 'project' | 'repository'>('scenes');
  const [snapshot, setSnapshot] = useState<{ source: string; destination: string } | null>(null);
  const [sidebarWidth, setSidebarWidth] = useState(480);
  const [resizing, setResizing] = useState(false);
  const novelSeq = useRef(0);

  const activeDiff = diffTabs.find((t) => t.id === activeDiffId) ?? null;

  // 项目打开时: 拉取 git 状态并监听文件变化防抖刷新
  useEffect(() => {
    if (!projectPath) return;
    void refreshGitStatus(projectPath);
    void startGitWatcher(projectPath);
    return () => {
      void stopGitWatcher();
    };
  }, [projectPath]);

  const MIN_SIDEBAR = 280;
  const MAX_SIDEBAR = 760;

  const activeDoc = documents.find((d) => d.path === activePath) ?? null;

  const toggleTheme = () => updateSettings({ theme: theme === 'dark' ? 'light' : 'dark' });

  /** 开始拖拽分隔条 (指针捕获, 移动时调整侧栏宽度) */
  const onResizeStart = (e: React.PointerEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    setResizing(true);
    document.body.classList.add('resizing');
  };

  const onResizeMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!resizing) return;
    const max = Math.min(MAX_SIDEBAR, Math.max(MIN_SIDEBAR, window.innerWidth - 320));
    setSidebarWidth(Math.min(Math.max(e.clientX, MIN_SIDEBAR), max));
  };

  const onResizeEnd = () => {
    setResizing(false);
    document.body.classList.remove('resizing');
  };

  /** 生成快照: 先处理未保存更改, 再选择输出位置。 */
  const startSnapshot = () => {
    if (!projectPath) return;
    confirmClose(() => void pickSnapshotLocation(), undefined, '生成快照前是否保存未保存的更改？');
  };

  /** 打开一个新的文本预处理选项卡 (非单例; id 全局唯一, 避免重挂载后计数器重置冲突)。 */
  const startNovelPreprocess = () => {
    novelSeq.current += 1;
    const id = `novel-${Date.now().toString(36)}-${novelSeq.current}`;
    openNovelTab({ id, title: `文本预处理 ${novelSeq.current}` });
  };

  /** 选择输出压缩包位置 (默认: 项目目录/<项目名>.zip)。 */
  const pickSnapshotLocation = async () => {
    if (!projectPath || !projectName) return;
    const defaultPath = `${projectPath.replace(/[\\/]+$/, '')}/${projectName}.zip`;
    const destination = await save({
      defaultPath,
      filters: [{ name: 'Zip 压缩包', extensions: ['zip'] }],
    });
    if (typeof destination !== 'string') return;
    setSnapshot({ source: projectPath, destination });
  };

  return (
    <div className="editor-page">
      <div className="top-bar">
        <Button
          appearance="subtle"
          icon={<ArrowLeftRegular />}
          title="关闭项目"
          onClick={() => confirmClose(() => closeProject())}
        />
        <span className="project-name">{projectName ?? '未命名项目'}</span>

        <span className="top-bar-spacer" />

        <Button appearance="subtle" icon={<DocumentTextRegular />} title="文本预处理" onClick={startNovelPreprocess} />
        <Button appearance="subtle" icon={<ArchiveRegular />} title="生成快照" onClick={startSnapshot} />
        <Button
          appearance="subtle"
          icon={theme === 'dark' ? <WeatherSunnyRegular /> : <WeatherMoonRegular />}
          title="切换主题"
          onClick={toggleTheme}
        />
        <Button
          appearance="subtle"
          icon={<SettingsRegular />}
          title="设置"
          onClick={() => {
            setSettingsCategory('general');
            setSettingsOpen(true);
          }}
        />
      </div>

      <div className="editor-main">
        {sidebarVisible ? (
          <>
            <div className="sidebar" style={{ width: sidebarWidth }}>
              <div className="sidebar-preview">
                <PreviewPanel />
              </div>
              <div className="sidebar-tabs">
                <button className={sidebarTab === 'project' ? 'active' : ''} onClick={() => setSidebarTab('project')}>
                  项目
                </button>
                <button
                  className={sidebarTab === 'repository' ? 'active' : ''}
                  onClick={() => setSidebarTab('repository')}
                >
                  仓库
                </button>
                <button className={sidebarTab === 'scenes' ? 'active' : ''} onClick={() => setSidebarTab('scenes')}>
                  场景
                </button>
                <button
                  className={sidebarTab === 'resources' ? 'active' : ''}
                  onClick={() => setSidebarTab('resources')}
                >
                  资源
                </button>
                <button className="sidebar-collapse" title="折叠侧栏" onClick={() => setSidebarVisible(false)}>
                  <PanelLeftContractRegular />
                </button>
              </div>
              <div className="sidebar-content">
                {sidebarTab === 'scenes' ? (
                  <SceneBrowser />
                ) : sidebarTab === 'resources' ? (
                  <ResourceBrowser />
                ) : sidebarTab === 'repository' ? (
                  <RepositoryTab />
                ) : (
                  <ProjectTab />
                )}
              </div>
            </div>
            <div
              className={`sidebar-resizer${resizing ? ' active' : ''}`}
              title="拖拽调整侧栏宽度"
              onPointerDown={onResizeStart}
              onPointerMove={onResizeMove}
              onPointerUp={onResizeEnd}
              onPointerCancel={onResizeEnd}
            />
          </>
        ) : (
          <button className="sidebar-expand" title="展开侧栏" onClick={() => setSidebarVisible(true)}>
            <PanelLeftExpandRegular />
          </button>
        )}

        <div className="editor-workspace">
          <EditorTabs />
          <div className="editor-area">
            {activeDiff ? (
              <GitDiffEditor tab={activeDiff} />
            ) : activeNovelId ? (
              <PreprocessTab id={activeNovelId} />
            ) : activeDoc ? (
              <CodeEditor doc={activeDoc} />
            ) : (
              <div className="editor-empty">从左侧选择或打开一个场景开始编辑</div>
            )}
          </div>
          <StatusBar />
        </div>
      </div>

      {snapshot && (
        <SnapshotDialog source={snapshot.source} destination={snapshot.destination} onClose={() => setSnapshot(null)} />
      )}
    </div>
  );
}
